export function topFamilies(entries, keep = 3) {
  const counts = new Map();
  for (const e of entries) counts.set(e.family, (counts.get(e.family) || 0) + 1);
  return [...counts].sort((a, b) => b[1] - a[1]).slice(0, keep).map(([f]) => f);
}

